    \label{lem: suff.card.tt.G}
Let \(G\in\text{Tri}(S,\underline{p})\) and let \([F]\in\mathcal{MF} (S,\underline{p})\).
Write
\[
i^{(G)}_{[F]} := \big(i([F],e)\big)_{e\in E(G)} \in \mathbb{R}^{E(G)}_{\ge 0}
\]
for the vector of geometric intersection numbers with the edges of \(G\).
Then:
\begin{itemize}
\item[(i)] \(i^{(G)}_{[F]} \in \Omega_G\);
\item[(ii)] \([F]\) is totally transverse to \(G\), i.e. \([F]\in \mathcal{MF}(G^{\perp})\).
\end{itemize}

\label{def:G.normal.form}
Let \(G\) be a triangulation of \((S,\underline p)\) and let \([F]\in \mathcal{MF} (S,\underline{p})\).
A representative \(F\) is in {\em \(G\)-normal form} if for every face \(f\in F(G)\), the restriction \(F|_f\) is in tripod normal form.

\label{lem:G-normal-form-existence}
Fix a triangulation \(G\) of \((S,\underline p)\).
Any $[F] \in \mathcal{MF} (S,\underline{p})$ admits a $G$-normal form $F_G$.

\label{def:feet.dual.arc}
Let \(F_G\) be the $G$-normal form of \([F]\in\mathcal{MF} (S,\underline{p})\) for a triangulation \(G\in\text{Tri}(S,\underline{p})\).
For each face \(f\in F(G)\), let \(q_f\) be the unique interior singularity of \(F_G\) in \(f\); the singular locus in \(f\) is a tripod with center \(q_f\).

For each edge \(e\in E(G)\), choose an orientation of \(e\) and denote by \(f^{(\mathrm{l})}_e\) and \(f^{(\mathrm{r})}_e\) the faces to the left and to the right of \(e\) (they may coincide, see Figure~\ref{subfig:shear_same_face}).
We define:
\begin{itemize}
    \item the {\em left} and {\em right singular feet} \(c^{(\mathrm{l})}_e, c^{(\mathrm{r})}_e \in e\) as the intersection points of \(e\) with the singular leaves issuing from \(q_{f^{(\mathrm{l})}_e}\) and \(q_{f^{(\mathrm{r})}_e}\), respectively; 
    \item the {\em dual arc} \(e^*\) of \(e\) as the unique (up to isotopy) arc contained in \(f^{(\mathrm{l})}_e \cup f^{(\mathrm{r})}_e\) which joins \(q_{f^{(\mathrm{l})}_e}\) to \(q_{f^{(\mathrm{r})}_e}\) and crosses \(e\) exactly once (and meets no other edge of \(G\)).
\end{itemize}

\label{def:MF.shear}
\label{def:MF.shear.map}
Let \(G\in\text{Tri}(S,\underline{p})\), \([F]\in\mathcal{MF} (S,\underline{p})\) and \(F_G\) be the \(G\)-normal form of \([F]\).
For an edge \(e\in E(G)\), fix an orientation of \(e\) and a base point \(b_e\in e\).
We define a coordinate map
\[
\iota_e : e \longrightarrow \mathbb{R}
\]
as follows: for any \(p\in e\), the value \(\iota_e(p)\) is the {\em signed distance} from \(b_e\) to \(p\), where the distance is the intersection number \(i(F_G,[b_e,p])\) (with \([b_e,p]\) the homotopy class of the segment in \(e\) joining \(b_e\) to \(p\)), taken with positive sign if the segment is oriented in the same direction as \(e\) and negative otherwise.

The {\em shear of \(F_G\) along \(e\)} is
\begin{equation}
    \label{eq:shear}
    s_e(F_G) := \iota_e\bigl(c^{(\mathrm{l})}_e\bigr) - \iota_e\bigl(c^{(\mathrm{r})}_e\bigr).
\end{equation}
This quantity is independent of the choice of base point \(b_e\) and of the choice of orientation of \(e\); its absolute value coincides with the intersection number \(i(F_G,e^*)\).
The {\em shear of \([F]\) along \(e\)} is defined by
\[
s_e([F]) := s_e(F_G).
\]

\label{rem:MF.shear.classical}
Our sign convention for \(s_e([F])\) is chosen so that, the collection \(\bigl(s_e([F])\bigr)_{e\in E(G)}\) agrees with Bonahon's shear cocycle \cite{Bon96} and with Thurston's shear coordinates for hyperbolic structures \cite{Thu98}.
Related shear-type coordinate systems have also been developed from different viewpoints: Pan--Wolf introduce shear--type coordinates associated to a fixed geodesic lamination via harmonic maps \cite{PW22}, and Calderon--Farre define shear--shape cocycles that extend the Bonahon--Thurston shear formalism to arbitrary measured laminations \cite{CF24}.

\label{lem:balanc.cond.}
For any triangulation \(G \in \text{Tri}(S,\underline{p})\) and any \([F] \in \mathcal{MF} (S,\underline{p})\), the sum of shears around any marked point \(p \in \underline{p}\) vanishes:
\begin{equation}\label{eq:shear-cond}
\sum_{e \in E_p(G)} s_{e}([F]) = 0,
\end{equation}
where \(E_p(G)\) is the star at \(p\) in \(G\) (see Definition~\ref{def:face.star}).

\label{def:arc.curve.leng.Teich.}
The {\em arc--curve length function} on \(\mathcal{T}(S,\underline p)\) is the map
\begin{equation}\label{eq:edge.length.Teich}
\ell^{(\mathcal{A} \cup \mathcal{C})}_{\cdot}: \mathcal{T} (S,\underline{p}) \to \mathbb{R}^{\mathcal{A}\cup\mathcal{C}}_{>0},\quad
X \mapsto \bigl(\ell_X([\beta])\bigr)_{[\beta]\in\mathcal{A} \cup \mathcal{C}}.
\end{equation}
where \(\ell_X([\beta])\) is the infimum of the lengths (with respect to \(X\)) of all curves or arcs in the homotopy class \([\beta]\) relative to \(\underline p\).
Any representative realizing this infimum is called the {\em length–minimizing} curve or arc for \([\beta]\) with respect to \(X\), and is denoted by \(\beta_X\). 
Note that this length-minimizer might fail to be homotopic to $\beta$ when its interior contains a marked point, but we still use the name `representative' for simplicity.

\label{def:edge.marking.triang.}
Let $\mu\in\mathcal{R}(\partial\Delta)$.  A map
$f_{\mu}:\partial\Delta_0\rightarrow\partial\Delta$ is called a
{\em $\mu$-marking of $\partial\Delta$} if
\begin{itemize}
\item[(i)] $f_{\mu}$ is an orientation-preserving homeomorphism sending the
  $i$-th vertex of $\Delta_0$ to the $i$-th vertex of $\Delta$ for $i=1,2,3$;
\item[(ii)] for each edge $e_i\subset\partial\Delta_0$ and each $t\in[0,1]$ we have
\begin{equation}\label{eq:def.mark.triang.}
\frac{\mu\big(f_{\mu}([e_i(0),e_i(t)])\big)}
     {\mu\big(f_{\mu}([e_i(0),e_i(1)])\big)}
= t,
\end{equation}
where $[a,b]$ denotes the closed sub-arc of $e_i$ joining $a$ to $b$.
\end{itemize}

\label{def:arc.triang.}
An {\em (oriented) arc} on a topological triangle \(\Delta\) is a continuous map \(\alpha:[0,1]\to\Delta\) with \(\alpha((0,1))\) contained in the interior of $\Delta$ and \(\alpha(0),\alpha(1)\) lying on \(\partial\Delta\).
We denote by \(\mathcal{A}(\Delta)\) the set of homotopy classes of arcs in \(\Delta\) relative to their endpoints, and by \(\mathcal{A}_0(\Delta)\subset\mathcal{A}(\Delta)\) the subset of classes of simple arcs.

\label{clm:express.I(p)}
Let $[F]\in\mathcal{MF}(\Delta^{\perp})$ and let $p$ be a point on the $j$-th edge of
$\Delta$. Then the signed intersection number $I_p([F])$ is given by
\begin{equation}
    I_p([F])
    = \frac{1}{2}\Big( (2t^{[F]}_p-1) \, i_{[F]}(e_j)
                      + i_{[F]}(e_{j+1}) - i_{[F]}(e_{j+2}) \Big),
\end{equation}
where the indices are taken cyclically in $\{1,2,3\}$.

The formulas follow directly from the geometric meaning of the signed
intersection number $I_p([F])$.
The quantity $|I_p([F])|$ is the transverse measure of the set
$\mathcal{F}_p$ of leaves whose endpoints on the edge $e_i$ containing $p$
lie between $p$ and the singular foot $c_i^{[F]}$.

\emph{Case~1: $p$ and $q$ lie on the same side of the singular locus.}
In this case, one of the sets $\mathcal{F}_p$ and $\mathcal{F}_q$ is contained
in the other; assume $\mathcal{F}_p \subseteq \mathcal{F}_q$.
An arc $[\alpha]$ connecting $p$ and $q$ crosses exactly the leaves in the set
difference $\mathcal{F}_q \setminus \mathcal{F}_p$
(Figure~\ref{fig:MF.inter.edge.case1}),
whose transverse measure is the absolute difference of the measures of
$\mathcal{F}_p$ and $\mathcal{F}_q$.
Thus
\[
    i_{[F]}([\alpha])
    = \big|\mathrm{measure}(\mathcal{F}_p)
             - \mathrm{measure}(\mathcal{F}_q)\big|
    = \big||I_p([F])| - |I_q([F])|\big|.
\]

\emph{Case~2: $p$ and $q$ lie on different sides of the singular locus.}
Here the sets $\mathcal{F}_p$ and $\mathcal{F}_q$ are disjoint, and any arc
$[\alpha]$ connecting $p$ and $q$ crosses all leaves in both sets
(Figure~\ref{fig:MF.inter.edge.case2}).
Therefore,
\[
    i_{[F]}([\alpha])
    = \mathrm{measure}(\mathcal{F}_p) + \mathrm{measure}(\mathcal{F}_q)
    = |I_p([F])| + |I_q([F])|.
\]

